def greedy(amount):
    count = 0
    for c in [4, 3, 1]:
        count += amount // c; amount %= c
    return count
def best(amount):
    dp = [0] + [9] * amount
    for a in range(1, amount + 1):
        dp[a] = 1 + min(dp[a - c] for c in [4, 3, 1] if c <= a)
    return dp[amount]
print(greedy(6), best(6))

ivs = [(1, 5), (2, 6), (8, 10)]
ivs.sort()
merged = []
for s, e in ivs:
    if merged and s <= merged[-1][1]:
        merged[-1][1] = max(merged[-1][1], e)
    else:
        merged.append([s, e])
print(merged)
